1	import React, { useEffect, useState } from 'react';
2	import type { Feature } from '../../router/routes';
3	
4	// Projects feature: add a project and pick which client it is for, then list every project showing
5	// the client's NAME. Opening a project (project-open-<id>) reveals its detail: the invoices raised
6	// against it, their running total, and a form to add another. Owns its own state; talks to its own
7	// /api/projects and /api/invoices endpoints and reads /api/clients to populate the client picker.
8	// data-testid anchors follow the spec's conventions.
9	type Client = { id: number; name: string; email: string };
10	type ProjectStatus = 'ACTIVE' | 'ON_HOLD' | 'FINISHED';
11	type Project = {
12	  id: number;
13	  name: string;
14	  clientId: number;
15	  clientName: string;
16	  archived: boolean;
17	  status: ProjectStatus;
18	};
19	type Invoice = {
20	  id: number;
21	  projectId: number;
22	  amount: number;
23	  amountDue: number;
24	  status: string;
25	  issuedDate: string;
26	  dueDate: string;
27	};
28	type Task = { id: number; projectId: number; title: string; done: boolean };
29	type Tag = { id: number; name: string };
30	type Note = { id: number; targetType: string; targetId: number; text: string; at: string };
31	
32	type LineItem = {
33	  id: number;
34	  invoiceId: number;
35	  description: string;
36	  qty: number;
37	  unitPrice: number;
38	};
39	
40	type Payment = { id: number; invoiceId: number; amount: number; date: string };
41	
42	function money(amount: number): string {
43	  return `$${Number(amount).toLocaleString('en-US', {
44	    minimumFractionDigits: 2,
45	    maximumFractionDigits: 2,
46	  })}`;
47	}
48	
49	// Budget figures are shown with thousands separators (e.g. $1,000.00) so larger amounts stay
50	// readable at a glance.
51	function moneyGrouped(amount: number): string {
52	  return `$${Number(amount).toLocaleString('en-US', {
53	    minimumFractionDigits: 2,
54	    maximumFractionDigits: 2,
55	  })}`;
56	}
57	
58	type ProjectBudget = { budget: number | null; invoiced: number; remaining: number | null };
59	
60	// One charge line while it is being edited on screen: the fields are held as raw strings so the
61	// inputs stay controlled and the total can recompute live as they change.
62	type EditItem = { id: number; description: string; qty: string; unitPrice: string };
63	
64	// An opened invoice's detail: the things it is charging for, listed as line items (description, how
65	// many, price each), the total worked out for you, and a form to add another line. Each line can be
66	// changed in place (save) or removed, and the total re-derives from whatever lines remain. Owns its
67	// own line-item state, scoped to the one invoice it is showing.
68	function InvoiceDetail({
69	  invoiceId,
70	  onChange,
71	  onClose,
72	}: {
73	  invoiceId: number;
74	  onChange: () => void;
75	  onClose: () => void;
76	}) {
77	  const [items, setItems] = useState<EditItem[]>([]);
78	  const [description, setDescription] = useState('');
79	  const [qty, setQty] = useState('');
80	  const [unitPrice, setUnitPrice] = useState('');
81	  const [payments, setPayments] = useState<Payment[]>([]);
82	  const [paymentAmount, setPaymentAmount] = useState('');
83	  const [paymentDate, setPaymentDate] = useState('');
84	  const [status, setStatus] = useState('');
85	
86	  // The status is worked out from the payments recorded against the invoice, so re-read it whenever
87	  // a payment is added rather than flipping it by hand.
88	  async function loadStatus() {
89	    const res = await fetch(`/api/invoices/${invoiceId}`);
90	    const inv: Invoice = await res.json();
91	    setStatus(inv.status);
92	  }
93	
94	  async function load() {
95	    const res = await fetch(`/api/invoices/${invoiceId}/line-items`);
96	    const rows: LineItem[] = await res.json();
97	    setItems(
98	      rows.map((li) => ({
99	        id: li.id,
100	        description: li.description,
101	        qty: String(li.qty),
102	        unitPrice: String(li.unitPrice),
103	      })),
104	    );
105	  }
106	
107	  async function loadPayments() {
108	    const res = await fetch(`/api/invoices/${invoiceId}/payments`);
109	    setPayments(await res.json());
110	  }
111	
112	  async function submitPayment(e: React.FormEvent) {
113	    e.preventDefault();
114	    const value = Number(paymentAmount);
115	    if (paymentAmount.trim() === '' || !Number.isFinite(value) || value <= 0) {
116	      return;
117	    }
118	    if (paymentDate.trim() === '') {
119	      return;
120	    }
121	    await fetch(`/api/invoices/${invoiceId}/payments`, {
122	      method: 'POST',
123	      headers: { 'Content-Type': 'application/json' },
124	      body: JSON.stringify({ amount: value, date: paymentDate }),
125	    });
126	    setPaymentAmount('');
127	    setPaymentDate('');
128	    await loadPayments();
129	    await loadStatus();
130	    onChange();
131	  }
132	
133	  useEffect(() => {
134	    void load();
135	    void loadPayments();
136	    void loadStatus();
137	  }, [invoiceId]);
138	
139	  function editField(id: number, field: 'description' | 'qty' | 'unitPrice', value: string) {
140	    setItems((prev) => prev.map((li) => (li.id === id ? { ...li, [field]: value } : li)));
141	  }
142	
143	  function amountOf(li: EditItem): number {
144	    const line = Number(li.qty) * Number(li.unitPrice);
145	    return Number.isFinite(line) ? line : 0;
146	  }
147	
148	  async function save(li: EditItem) {
149	    if (!li.description.trim() || li.qty.trim() === '' || li.unitPrice.trim() === '') {
150	      return;
151	    }
152	    await fetch(`/api/invoices/${invoiceId}/line-items/${li.id}/update`, {
153	      method: 'POST',
154	      headers: { 'Content-Type': 'application/json' },
155	      body: JSON.stringify({
156	        description: li.description,
157	        qty: Number(li.qty),
158	        unitPrice: Number(li.unitPrice),
159	      }),
160	    });
161	    await load();
162	    onChange();
163	  }
164	
165	  async function remove(id: number) {
166	    await fetch(`/api/invoices/${invoiceId}/line-items/${id}/remove`, { method: 'POST' });
167	    await load();
168	    onChange();
169	  }
170	
171	  async function submit(e: React.FormEvent) {
172	    e.preventDefault();
173	    if (!description.trim() || qty.trim() === '' || unitPrice.trim() === '') {
174	      return;
175	    }
176	    await fetch(`/api/invoices/${invoiceId}/line-items`, {
177	      method: 'POST',
178	      headers: { 'Content-Type': 'application/json' },
179	      body: JSON.stringify({
180	        description,
181	        qty: Number(qty),
182	        unitPrice: Number(unitPrice),
183	      }),
184	    });
185	    setDescription('');
186	    setQty('');
187	    setUnitPrice('');
188	    await load();
189	    onChange();
190	  }
191	
192	  const total = items.reduce((sum, li) => sum + amountOf(li), 0);
193	
194	  return (
195	    <section data-testid="invoice-detail">
196	      <button data-testid="invoice-detail-close" type="button" onClick={onClose}>
197	        Back to invoices
198	      </button>
199	
200	      <p data-testid="invoice-status">{status}</p>
201	
202	      <table data-testid="invoice-lineitems-table">
203	        <tbody>
204	          {items.map((li) => (
205	            <tr key={li.id} data-testid={`lineitem-row-${li.id}`}>
206	              <td>
207	                <input
208	                  data-testid="lineitem-description"
209	                  value={li.description}
210	                  onChange={(e) => editField(li.id, 'description', e.target.value)}
211	                />
212	              </td>
213	              <td>
214	                <input
215	                  data-testid="lineitem-qty"
216	                  value={li.qty}
217	                  onChange={(e) => editField(li.id, 'qty', e.target.value)}
218	                />
219	              </td>
220	              <td>
221	                <input
222	                  data-testid="lineitem-unitprice"
223	                  value={li.unitPrice}
224	                  onChange={(e) => editField(li.id, 'unitPrice', e.target.value)}
225	                />
226	              </td>
227	              <td data-testid="lineitem-amount">{money(amountOf(li))}</td>
228	              <td>
229	                <button
230	                  data-testid={`lineitem-save-${li.id}`}
231	                  type="button"
232	                  onClick={() => save(li)}
233	                >
234	                  Save
235	                </button>
236	                <button
237	                  data-testid={`lineitem-remove-${li.id}`}
238	                  type="button"
239	                  onClick={() => remove(li.id)}
240	                >
241	                  Remove
242	                </button>
243	              </td>
244	            </tr>
245	          ))}
246	        </tbody>
247	      </table>
248	
249	      <p data-testid="invoice-amount">{money(total)}</p>
250	
251	      <form data-testid="lineitem-form" onSubmit={submit}>
252	        <input
253	          data-testid="lineitem-form-description"
254	          placeholder="Description"
255	          value={description}
256	          onChange={(e) => setDescription(e.target.value)}
257	        />
258	        <input
259	          data-testid="lineitem-form-qty"
260	          placeholder="How many"
261	          value={qty}
262	          onChange={(e) => setQty(e.target.value)}
263	        />
264	        <input
265	          data-testid="lineitem-form-unitprice"
266	          placeholder="Price each"
267	          value={unitPrice}
268	          onChange={(e) => setUnitPrice(e.target.value)}
269	        />
270	        <button data-testid="lineitem-form-submit" type="submit">
271	          Add line item
272	        </button>
273	      </form>
274	
275	      <table data-testid="invoice-payments-table">
276	        <tbody>
277	          {payments.map((p) => (
278	            <tr key={p.id} data-testid={`payment-row-${p.id}`}>
279	              <td data-testid="payment-amount">{money(p.amount)}</td>
280	              <td data-testid="payment-date">{p.date}</td>
281	            </tr>
282	          ))}
283	        </tbody>
284	      </table>
285	
286	      <form data-testid="payment-form" onSubmit={submitPayment}>
287	        <input
288	          data-testid="payment-form-amount"
289	          placeholder="Amount paid"
290	          value={paymentAmount}
291	          onChange={(e) => setPaymentAmount(e.target.value)}
292	        />
293	        <input
294	          data-testid="payment-form-date"
295	          type="date"
296	          value={paymentDate}
297	          onChange={(e) => setPaymentDate(e.target.value)}
298	        />
299	        <button data-testid="payment-form-submit" type="submit">
300	          Record payment
301	        </button>
302	      </form>
303	    </section>
304	  );
305	}
306	
307	// A project's detail: its invoices, what they add up to, and a form to add a new invoice. Owns its
308	// own invoice state, scoped to the one project it is showing.
309	function ProjectDetail({ project }: { project: Project }) {
310	  const [invoices, setInvoices] = useState<Invoice[]>([]);
311	  const [tasks, setTasks] = useState<Task[]>([]);
312	  const [tags, setTags] = useState<Tag[]>([]);
313	  const [allTags, setAllTags] = useState<Tag[]>([]);
314	  const [tagToAdd, setTagToAdd] = useState('');
315	  const [taskFilter, setTaskFilter] = useState<'ALL' | 'OPEN' | 'DONE'>('ALL');
316	  const [amount, setAmount] = useState('');
317	  const [amountError, setAmountError] = useState('');
318	  const [sortByDue, setSortByDue] = useState(false);
319	  const [openInvoiceId, setOpenInvoiceId] = useState<number | null>(null);
320	  const [notes, setNotes] = useState<Note[]>([]);
321	  const [noteText, setNoteText] = useState('');
322	  const [budget, setBudget] = useState<ProjectBudget | null>(null);
323	  const [budgetInput, setBudgetInput] = useState('');
324	
325	  async function loadBudget() {
326	    const res = await fetch(`/api/projects/${project.id}/budget`);
327	    setBudget(await res.json());
328	  }
329	
330	  async function load() {
331	    const res = await fetch(`/api/invoices?projectId=${project.id}`);
332	    setInvoices(await res.json());
333	    // Invoiced (and so remaining) is derived from the project's invoices, so re-read the budget
334	    // picture whenever the invoices change.
335	    await loadBudget();
336	  }
337	
338	  async function submitBudget(e: React.FormEvent) {
339	    e.preventDefault();
340	    const value = Number(budgetInput);
341	    if (budgetInput.trim() === '' || !Number.isFinite(value) || value < 0) {
342	      return;
343	    }
344	    await fetch(`/api/projects/${project.id}/budget`, {
345	      method: 'POST',
346	      headers: { 'Content-Type': 'application/json' },
347	      body: JSON.stringify({ budget: value }),
348	    });
349	    setBudgetInput('');
350	    await loadBudget();
351	  }
352	
353	  async function loadNotes() {
354	    const res = await fetch(`/api/notes?targetType=project&targetId=${project.id}`);
355	    setNotes(await res.json());
356	  }
357	
358	  async function submitNote(e: React.FormEvent) {
359	    e.preventDefault();
360	    if (!noteText.trim()) {
361	      return;
362	    }
363	    await fetch('/api/notes', {
364	      method: 'POST',
365	      headers: { 'Content-Type': 'application/json' },
366	      body: JSON.stringify({ targetType: 'project', targetId: project.id, text: noteText }),
367	    });
368	    setNoteText('');
369	    await loadNotes();
370	  }
371	
372	  async function loadTasks() {
373	    const res = await fetch(`/api/tasks?projectId=${project.id}`);
374	    setTasks(await res.json());
375	  }
376	
377	  async function loadTags() {
378	    const [mine, all] = await Promise.all([
379	      fetch(`/api/projects/${project.id}/tags`).then((r) => r.json()),
380	      fetch('/api/tags').then((r) => r.json()),
381	    ]);
382	    setTags(mine);
383	    setAllTags(all);
384	  }
385	
386	  useEffect(() => {
387	    void load();
388	    void loadTasks();
389	    void loadTags();
390	    void loadNotes();
391	  }, [project.id]);
392	
393	  async function toggleTask(id: number) {
394	    await fetch(`/api/tasks/${id}/toggle`, { method: 'POST' });
395	    await loadTasks();
396	  }
397	
398	  async function addTag(e: React.FormEvent) {
399	    e.preventDefault();
400	    if (!tagToAdd) {
401	      return;
402	    }
403	    await fetch(`/api/projects/${project.id}/tags`, {
404	      method: 'POST',
405	      headers: { 'Content-Type': 'application/json' },
406	      body: JSON.stringify({ tagId: Number(tagToAdd) }),
407	    });
408	    setTagToAdd('');
409	    await loadTags();
410	  }
411	
412	  async function removeTag(id: number) {
413	    await fetch(`/api/projects/${project.id}/tags/${id}/remove`, { method: 'POST' });
414	    await loadTags();
415	  }
416	
417	  async function submit(e: React.FormEvent) {
418	    e.preventDefault();
419	    const value = Number(amount);
420	    if (amount.trim() === '' || !Number.isFinite(value) || value <= 0) {
421	      setAmountError('Amount must be more than zero');
422	      return;
423	    }
424	    setAmountError('');
425	    await fetch('/api/invoices', {
426	      method: 'POST',
427	      headers: { 'Content-Type': 'application/json' },
428	      body: JSON.stringify({ projectId: project.id, amount: Number(amount) }),
429	    });
430	    setAmount('');
431	    await load();
432	  }
433	
434	  async function send(id: number) {
435	    await fetch(`/api/invoices/${id}/send`, { method: 'POST' });
436	    await load();
437	  }
438	
439	  async function pay(id: number) {
440	    await fetch(`/api/invoices/${id}/pay`, { method: 'POST' });
441	    await load();
442	  }
443	
444	  const shownTasks = tasks.filter((t) =>
445	    taskFilter === 'OPEN' ? !t.done : taskFilter === 'DONE' ? t.done : true,
446	  );
447	
448	  const total = invoices.reduce((sum, inv) => sum + Number(inv.amount), 0);
449	  const shownInvoices = sortByDue
450	    ? [...invoices].sort((a, b) => a.dueDate.localeCompare(b.dueDate))
451	    : invoices;
452	
453	  return (
454	    <section data-testid="project-detail">
455	      <h2 data-testid="project-detail-name">{project.name}</h2>
456	
457	      <section data-testid="project-budget-panel">
458	        <p data-testid="project-budget">
459	          {budget && budget.budget != null ? moneyGrouped(budget.budget) : ''}
460	        </p>
461	        <p data-testid="project-invoiced">{moneyGrouped(budget ? budget.invoiced : 0)}</p>
462	        <p data-testid="project-remaining">
463	          {budget && budget.remaining != null ? moneyGrouped(budget.remaining) : ''}
464	        </p>
465	        <form data-testid="project-budget-form" onSubmit={submitBudget}>
466	          <input
467	            data-testid="project-budget-input"
468	            placeholder="Budget"
469	            value={budgetInput}
470	            onChange={(e) => setBudgetInput(e.target.value)}
471	          />
472	          <button data-testid="project-budget-submit" type="submit">
473	            Set budget
474	          </button>
475	        </form>
476	      </section>
477	
478	      <div data-testid="project-tags">
479	        {tags.map((tag) => (
480	          <span key={tag.id}>
481	            <span data-testid={`project-tag-${tag.id}`}>{tag.name}</span>
482	            <button
483	              data-testid={`project-tag-remove-${tag.id}`}
484	              type="button"
485	              onClick={() => removeTag(tag.id)}
486	            >
487	              Remove
488	            </button>
489	          </span>
490	        ))}
491	      </div>
492	
493	      <form data-testid="project-tag-form" onSubmit={addTag}>
494	        <select
495	          data-testid="project-tag-add"
496	          value={tagToAdd}
497	          onChange={(e) => setTagToAdd(e.target.value)}
498	        >
499	          <option value="">Add a label</option>
500	          {allTags
501	            .filter((t) => !tags.some((mine) => mine.id === t.id))
502	            .map((t) => (
503	              <option key={t.id} value={String(t.id)}>
504	                {t.name}
505	              </option>
506	            ))}
507	        </select>
508	        <button data-testid="project-tag-add-submit" type="submit">
509	          Add label
510	        </button>
511	      </form>
512	
513	      <select
514	        data-testid="task-filter"
515	        value={taskFilter}
516	        onChange={(e) => setTaskFilter(e.target.value as 'ALL' | 'OPEN' | 'DONE')}
517	      >
518	        <option value="ALL">All tasks</option>
519	        <option value="OPEN">Open</option>
520	        <option value="DONE">Done</option>
521	      </select>
522	
523	      <table data-testid="project-tasks-table">
524	        <tbody>
525	          {shownTasks.map((t) => (
526	            <tr key={t.id} data-testid={`task-row-${t.id}`}>
527	              <td data-testid="task-title">{t.title}</td>
528	              <td data-testid="task-status">{t.done ? 'DONE' : 'OPEN'}</td>
529	              <td>
530	                <button data-testid={`task-toggle-${t.id}`} onClick={() => toggleTask(t.id)}>
531	                  {t.done ? 'Reopen' : 'Tick off'}
532	                </button>
533	              </td>
534	            </tr>
535	          ))}
536	        </tbody>
537	      </table>
538	
539	      <section data-testid="project-notes">
540	        <form data-testid="note-form" onSubmit={submitNote}>
541	          <input
542	            data-testid="note-form-text"
543	            placeholder="Write a note"
544	            value={noteText}
545	            onChange={(e) => setNoteText(e.target.value)}
546	          />
547	          <button data-testid="note-form-submit" type="submit">
548	            Add note
549	          </button>
550	        </form>
551	
552	        <ul data-testid="project-notes-list">
553	          {notes.map((n) => (
554	            <li key={n.id} data-testid={`note-row-${n.id}`}>
555	              <span data-testid="note-text">{n.text}</span>
556	            </li>
557	          ))}
558	        </ul>
559	      </section>
560	
561	      <form data-testid="invoice-form" onSubmit={submit}>
562	        <input
563	          data-testid="invoice-form-amount"
564	          placeholder="Amount"
565	          value={amount}
566	          onChange={(e) => setAmount(e.target.value)}
567	        />
568	        <button data-testid="invoice-form-submit" type="submit">
569	          Add invoice
570	        </button>
571	        {amountError && (
572	          <p data-testid="invoice-form-amount-error" role="alert">
573	            {amountError}
574	          </p>
575	        )}
576	      </form>
577	
578	      <button data-testid="invoice-sort-due" type="button" onClick={() => setSortByDue(true)}>
579	        Sort by due date
580	      </button>
581	
582	      {openInvoiceId === null ? (
583	        <>
584	          <table data-testid="project-invoices-table">
585	            <tbody>
586	              {shownInvoices.map((inv) => (
587	                <tr key={inv.id} data-testid={`invoice-row-${inv.id}`}>
588	                  <td data-testid="invoice-amount">{money(inv.amount)}</td>
589	                  <td data-testid="invoice-due-amount">{money(inv.amountDue)}</td>
590	                  <td data-testid="invoice-issued">{inv.issuedDate}</td>
591	                  <td data-testid="invoice-due">{inv.dueDate}</td>
592	                  <td data-testid="invoice-status">{inv.status}</td>
593	                  <td>
594	                    <button
595	                      data-testid={`invoice-open-${inv.id}`}
596	                      onClick={() => setOpenInvoiceId(inv.id)}
597	                    >
598	                      Open
599	                    </button>
600	                    {inv.status === 'DRAFT' && (
601	                      <button data-testid={`invoice-send-${inv.id}`} onClick={() => send(inv.id)}>
602	                        Send
603	                      </button>
604	                    )}
605	                    {inv.status === 'SENT' && (
606	                      <button data-testid={`invoice-pay-${inv.id}`} onClick={() => pay(inv.id)}>
607	                        Mark paid
608	                      </button>
609	                    )}
610	                  </td>
611	                </tr>
612	              ))}
613	            </tbody>
614	          </table>
615	
616	          <p data-testid="project-invoices-total">{money(total)}</p>
617	        </>
618	      ) : (
619	        <InvoiceDetail
620	          invoiceId={openInvoiceId}
621	          onChange={load}
